        int t = int(sqrt(i) + eps);
        if (i >= a && t * t == i)
            is_lucky[i] = 1;
        if (! is_lucky[i])
            continue ;

        for (int j = i + i; j <= N; j += i)
            is_lucky[j] = 1;
